interface CorbelMarkProps {
  size?: number | string;
  variant?: "gold" | "white" | "dark" | "keystone";
  className?: string;
  style?: React.CSSProperties;
}

/**
 * Corbel 3-lobe fluid mark (Observe, Build, Verify)
 */
export const CorbelMark: React.FC<CorbelMarkProps> = ({
  size = 32,
  variant = "gold",
  className,
  style,
}) => {
  const isGold = variant === "gold" || variant === "keystone";
  const fill =
    variant === "white"
      ? "#FFFFFF"
      : variant === "dark"
      ? "#111827"
      : "url(#corbelGoldGrad)";

  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 512 512"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      style={{ display: "inline-block", flexShrink: 0, ...style }}
    >
      <defs>
        {isGold && (
          <linearGradient
            id="corbelGoldGrad"
            x1="0%"
            y1="0%"
            x2="100%"
            y2="100%"
          >
            <stop offset="0%" stopColor="#FFF3CE" />
            <stop offset="25%" stopColor="#E9C667" />
            <stop offset="65%" stopColor="#C9952A" />
            <stop offset="100%" stopColor="#9C6B14" />
          </linearGradient>
        )}
      </defs>
      <g fill={fill}>
        <path d={PATH_TOP} />
        <path d={PATH_BASE} />
        <path d={PATH_DROPLET} />
        {variant === "keystone" && (
          <polygon points="256,236 276,256 256,276 236,256" fill="#FFFCEB" />
        )}
      </g>
    </svg>
  );
};

interface CorbelSquircleProps {
  size?: number | string;
  variant?: "gold" | "teal" | "keystone" | "mono";
  className?: string;
  style?: React.CSSProperties;
}

/**
 * Official Corbel squircle app icon container
 */
export const CorbelSquircle: React.FC<CorbelSquircleProps> = ({
  size = 48,
  variant = "gold",
  className,
  style,
}) => {
  const isTeal = variant === "teal";
  const isMono = variant === "mono";
  const isGold = variant === "gold" || variant === "keystone";

  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 512 512"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      style={{ display: "inline-block", flexShrink: 0, ...style }}
    >
      <defs>
        {isGold && (
          <>
            <linearGradient
              id="corbelSqNavy"
              x1="0%"
              y1="0%"
              x2="100%"
              y2="100%"
            >
              <stop offset="0%" stopColor="#0E1530" />
              <stop offset="55%" stopColor="#141C3B" />
              <stop offset="100%" stopColor="#1B274F" />
            </linearGradient>
            <linearGradient
              id="corbelSqGold"
              x1="0%"
              y1="0%"
              x2="100%"
              y2="100%"
            >
              <stop offset="0%" stopColor="#FFF3CE" />
              <stop offset="25%" stopColor="#E9C667" />
              <stop offset="65%" stopColor="#C9952A" />
              <stop offset="100%" stopColor="#9C6B14" />
            </linearGradient>
          </>
        )}
        {isTeal && (
          <linearGradient
            id="corbelSqTeal"
            x1="0%"
            y1="0%"
            x2="100%"
            y2="100%"
          >
            <stop offset="0%" stopColor="#0F5B6D" />
            <stop offset="50%" stopColor="#0C5162" />
            <stop offset="100%" stopColor="#083E4C" />
          </linearGradient>
        )}
      </defs>

      {!isMono && (
        <>
          <rect
            x="20"
            y="20"
            width="472"
            height="472"
            rx="112"
            fill={isTeal ? "url(#corbelSqTeal)" : "url(#corbelSqNavy)"}
            stroke={isTeal ? "#17778F" : "#253360"}
            strokeWidth="2.5"
          />
          <rect
            x="22"
            y="22"
            width="468"
            height="468"
            rx="110"
            fill="none"
            stroke="#FFFFFF"
            strokeOpacity="0.10"
            strokeWidth="1.5"
          />
        </>
      )}

      <g
        fill={
          isMono
            ? "#111827"
            : isTeal
            ? "#FFFFFF"
            : "url(#corbelSqGold)"
        }
      >
        <path d={PATH_TOP} />
        <path d={PATH_BASE} />
        <path d={PATH_DROPLET} />
        {variant === "keystone" && (
          <polygon points="256,236 276,256 256,276 236,256" fill="#FFFCEB" />
        )}
      </g>
    </svg>
  );
};

interface CorbelLockupProps {
  height?: number | string;
  variant?: "dark" | "light" | "gold";
  className?: string;
  style?: React.CSSProperties;
}

/**
 * Full Horizontal Brand Lockup (Mark + 'corbel' typography)
 */
export const CorbelLockup: React.FC<CorbelLockupProps> = ({
  height = 36,
  variant = "dark",
  className,
  style,
}) => {
  const isDark = variant === "dark";
  const isGold = variant === "gold";

  // Mark transformation inside lockup viewBox (0 0 820 220)
  // Scale = 0.54, Center Y = 110, Dx = -8.24, Dy = -28.24
  const markFill =
    isDark || isGold ? "url(#corbelLockupGold)" : "#111827";
  const textFill =
    isGold ? "url(#corbelLockupGold)" : isDark ? "#FFFFFF" : "#111827";

  return (
    <svg
      height={height}
      viewBox="0 0 820 220"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      className={className}
      style={{ display: "inline-block", verticalAlign: "middle", ...style }}
    >
      <defs>
        {(isDark || isGold) && (
          <linearGradient
            id="corbelLockupGold"
            x1="0%"
            y1="0%"
            x2="100%"
            y2="100%"
          >
            <stop offset="0%" stopColor="#FFF3CE" />
            <stop offset="25%" stopColor="#E9C667" />
            <stop offset="65%" stopColor="#C9952A" />
            <stop offset="100%" stopColor="#9C6B14" />
          </linearGradient>
        )}
      </defs>

      {/* 3-lobe mark */}
      <g
        transform="translate(-8.24, -28.24) scale(0.54)"
        fill={markFill}
      >
        <path d={PATH_TOP} />
        <path d={PATH_BASE} />
        <path d={PATH_DROPLET} />
      </g>

      {/* 'corbel' typography */}
      <g transform="translate(245, 172)" fill={textFill}>
        <path d={PATH_WORDMARK} />
      </g>
    </svg>
  );
};
